import { useState } from "react";
const initial = [{ id: 1, titre: "Web" }, { id: 2, titre: "Code" }];
export default function App() {
  const [livres, setLivres] = useState(initial);
  const [recherche, setRecherche] = useState("");
  const visibles = livres.filter(livre => livre.titre.toLowerCase().includes(recherche.toLowerCase()));
  return <main><h1>Livres</h1><label>Rechercher <input value={recherche} onChange={e => setRecherche(e.target.value)} /></label>
    <button type="button" onClick={() => setLivres(l => [...l, { id: 3, titre: "Réseau" }])}>Ajouter</button>
    <ul>{visibles.map(livre => <li key={livre.id}>{livre.titre}</li>)}</ul></main>;
}
